//! How large a texel is, generated from maplibre-native.
//!
//! Source revision: ad5e73527f3a
//!
//! From `Texture2DDesc::channelCount` and
//! `Texture2DDesc::channelStorageSize`. The enums alone say which
//! formats exist and not how large a pixel of each is, which is enough
//! for a producer — every caller sizes its own slice — and not enough
//! for a consumer: a whole-texture upload's byte count can only be
//! checked against its extent by something that knows this.
//!
//! Generated by `cargo run -p mbgl-codegen`. Do not edit.

use crate::generated::mbgl_enums::{TextureChannelDataType, TexturePixelType};

impl TexturePixelType {
    /// How many channels one pixel of this format carries.
    ///
    /// Half of a texel's size. The other half is
    /// [`TextureChannelDataType::storage_size`], and mbgl multiplies the
    /// two in `getStorageSize` — so anything sizing a texture here must
    /// too. This used to carry a note saying every channel on this stream
    /// was one byte; a color relief's elevation stops are `Float`, and it
    /// stopped being true.
    #[must_use]
    pub const fn channels(self) -> u32 {
        match self {
            Self::Alpha => 1,
            Self::Depth => 1,
            Self::Luminance => 1,
            Self::Stencil => 1,
            Self::RGBA => 4,
        }
    }
}

impl TextureChannelDataType {
    /// How many bytes one channel of this type occupies.
    ///
    /// The other half of a texel's size, from
    /// `Texture2DDesc::channelStorageSize`. A consumer that assumes one
    /// byte reads a `Float` texture at a quarter of its stride, which
    /// lands the right rows at the wrong addresses rather than failing.
    #[must_use]
    pub const fn storage_size(self) -> u32 {
        match self {
            Self::Float => 4,
            Self::HalfFloat => 2,
            Self::UnsignedByte => 1,
        }
    }
}
